-- Supabase Schema and Data Migration Script (4+ Questions Per Unit)

CREATE TABLE IF NOT EXISTS branches (id TEXT PRIMARY KEY, name TEXT NOT NULL, icon TEXT);
CREATE TABLE IF NOT EXISTS semesters (id UUID PRIMARY KEY, branch_id TEXT REFERENCES branches(id) ON DELETE CASCADE, semester INT NOT NULL, year INT NOT NULL);
CREATE TABLE IF NOT EXISTS subjects (code TEXT PRIMARY KEY, semester_id UUID REFERENCES semesters(id) ON DELETE CASCADE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS units (id UUID PRIMARY KEY, subject_code TEXT REFERENCES subjects(code) ON DELETE CASCADE, number INT NOT NULL, title TEXT NOT NULL, topics JSONB NOT NULL, high_yield INT NOT NULL);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, unit_id UUID REFERENCES units(id) ON DELETE CASCADE, q TEXT NOT NULL, options JSONB NOT NULL, answer TEXT NOT NULL, topic TEXT NOT NULL);

ALTER TABLE branches ENABLE ROW LEVEL SECURITY;
ALTER TABLE semesters ENABLE ROW LEVEL SECURITY;
ALTER TABLE subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE units ENABLE ROW LEVEL SECURITY;
ALTER TABLE questions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read access on branches" ON branches;
CREATE POLICY "Allow public read access on branches" ON branches FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read access on semesters" ON semesters;
CREATE POLICY "Allow public read access on semesters" ON semesters FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read access on subjects" ON subjects;
CREATE POLICY "Allow public read access on subjects" ON subjects FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read access on units" ON units;
CREATE POLICY "Allow public read access on units" ON units FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read access on questions" ON questions;
CREATE POLICY "Allow public read access on questions" ON questions FOR SELECT USING (true);

DELETE FROM branches;


